    ctypes.POINTER(GSLFunction),
    ctypes.c_double,
    ctypes.c_double,
    ctypes.c_double,
    ctypes.c_double,
    ctypes.c_size_t,
    ctypes.POINTER(CQuadWorkspace),
]
gsl.gsl_integration_cquad.restype = ctypes.c_int

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    try:
        gsl.gsl_integration_cquad.argtypes = [
            ctypes.POINTER(GSLFunction),
            ctypes.c_double,
            ctypes.c_double,
            ctypes.c_double,
            ctypes.c_double,
            ctypes.c_size_t,
            ctypes.POINTER(CQuadWorkspace),
        ]
        gsl.gsl_integration_cquad.restype = ctypes.c_int

        def c_func(x):
            return func(x)

        gsl_func = GSLFunction()
        gsl_func.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(c_func)

        workspace = CQuadWorkspace()
        status = gsl.gsl_integration_cquad(
            ctypes.byref(gsl_func), a, b, epsabs, epsrel, workspace_size, ctypes.byref(workspace)
        )

        if status == 0:
            integral = workspace.result
            abs_error = workspace.abserr
            neval = workspace.neval
            return json.dumps({"Candidate_solution": f"{integral} {abs_error} {neval}"})
        else:
            raise Exception(f"Error code: {status}")

