class GSLMatrix(ctypes.Structure):
    _fields_ = [("rows", ctypes.c_int), ("cols", ctypes.c_int), ("data", ctypes.POINTER(ctypes.c_double))]

def gsl_matrix_alloc(rows, cols):
    matrix = GSLMatrix()
    matrix.rows = rows
    matrix.cols = cols
    matrix.data = ctypes.POINTER(ctypes.c_double)()
    return matrix

def gsl_matrix_free(matrix):
    for i in range(matrix.rows):
        ctypes.memmove(matrix.data + i * matrix.cols, 0, matrix.cols * ctypes.sizeof(ctypes.c_double))
    ctypes.free(matrix.data)

def numpy_to_gsl_matrix(np_array):
    gsl_matrix = gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    ctypes.memmove(gsl_matrix.data, np_array.ctypes.data, np_array.size * np.ctypes.sizeof(np.double))
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    np_array = np.zeros((gsl_matrix.rows, gsl_matrix.cols), dtype=np.double)
    ctypes.memmove(np_array.ctypes.data, gsl_matrix.data, np_array.size * np.ctypes.sizeof(np.double))
    return np_array

