    if dimensions <= 0:
        raise ValueError("Invalid dimensions.")

    gsl_jacobian = numpy_to_gsl_matrix(jacobian)

    covariance_matrix = GSLMatrix(dimensions, dimensions)
    gsl.gsl_multifit_covar(gsl_jacobian.matrix, epsrel, covariance_matrix.matrix)

    return gsl_matrix_to_numpy(covariance_matrix)

