class GSLMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))(*map(float, sum(matrix, [])))

def is_positive_definite(matrix):
    gsl_matrix = GSLMatrix(matrix)
    gsl.gsl_matrix_set(gsl_matrix, gsl_matrix.rows, gsl_matrix.cols, gsl_matrix.data)
    return gsl.gsl_linalg_cholesky_is_pd(gsl_matrix)

def cholesky_decomp(matrix):
    gsl_matrix = GSLMatrix(matrix)
    gsl.gsl_matrix_set(gsl_matrix, gsl_matrix.rows, gsl_matrix.cols, gsl_matrix.data)
    status = gsl.gsl_linalg_cholesky_decomp(gsl_matrix)
    if status != 0:
        raise ValueError("Cholesky decomposition failed.")
    return [[gsl_matrix.data[i + j * gsl_matrix.rows] for j in range(i + 1)] for i in range(gsl_matrix.rows)]

